def choose_move(observation):
    # Defensive access with .get, defaulting to empty dict if keys are missing
    my_pos = observation.get('player', {}).get('pos', (0, 0))
    grid_size = observation.get('grid_size', (1, 1))
    width, height = grid_size

    # Helper function to clamp movement within grid bounds
    def clamp(n, min_n, max_n):
        return max(min(n, max_n), min_n)

    # Initialize desired move
    dx, dy = 0, 0

    # Check for resource_collection scenario
    resources = observation.get('resources', [])
    if resources:
        # Move towards the closest resource
        min_dist = float('inf')
        target_res = None
        for res in resources:
            res_pos = res.get('pos', (0, 0))
            dist = abs(res_pos[0] - my_pos[0]) + abs(res_pos[1] - my_pos[1])
            if dist < min_dist:
                min_dist = dist
                target_res = res_pos
        if target_res:
            if target_res[0] > my_pos[0]:
                dx = 1
            elif target_res[0] < my_pos[0]:
                dx = -1
            else:
                dx = 0
            if target_res[1] > my_pos[1]:
                dy = 1
            elif target_res[1] < my_pos[1]:
                dy = -1
            else:
                dy = 0
            return [dx, dy]

    # Check for pursuit_evasion scenario
    opponents = observation.get('opponents', [])
    if opponents:
        # Move towards the closest opponent
        min_dist = float('inf')
        target_opponent = None
        for opp in opponents:
            opp_pos = opp.get('pos', (0, 0))
            dist = abs(opp_pos[0] - my_pos[0]) + abs(opp_pos[1] - my_pos[1])
            if dist < min_dist:
                min_dist = dist
                target_opponent = opp_pos
        if target_opponent:
            if target_opponent[0] > my_pos[0]:
                dx = 1
            elif target_opponent[0] < my_pos[0]:
                dx = -1
            else:
                dx = 0
            if target_opponent[1] > my_pos[1]:
                dy = 1
            elif target_opponent[1] < my_pos[1]:
                dy = -1
            else:
                dy = 0
            return [dx, dy]

    # Check for territory_control scenario
    # For simplicity, move towards the center of the grid
    center = (width // 2, height // 2)
    if my_pos != center:
        if center[0] > my_pos[0]:
            dx = 1
        elif center[0] < my_pos[0]:
            dx = -1
        else:
            dx = 0
        if center[1] > my_pos[1]:
            dy = 1
        elif center[1] < my_pos[1]:
            dy = -1
        else:
            dy = 0
    return [dx, dy]

